          Select Store from the list
        </button>
                <button class="btn btn-primary" @click="conversion_factor = !conversion_factor; getStores(); selectedStore.id !== 'all' && getStoreItems(selectedStore.id);" v-if="selectedStore && user_permissions.includes('can_create_bin_card')">
                   <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" fill="currentColor" class="bi bi-plus-square" viewBox="0 0 16 16"> <path d="M14 1a1 1 0 0 1 1 1v12a1 1 0 0 1-1 1H2a1 1 0 0 1-1-1V2a1 1 0 0 1 1-1zM2 0a2 2 0 0 0-2 2v12a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V2a2 2 0 0 0-2-2z"/> <path d="M8 4a.5.5 0 0 1 .5.5v3h3a.5.5 0 0 1 0 1h-3v3a.5.5 0 0 1-1 0v-3h-3a.5.5 0 0 1 0-1h3v-3A.5.5 0 0 1 8 4"/> </svg>
                </button>
            </div>
                 
        </div>


              <!-- offcanvas start -->
        <div class="offcanvas offcanvas-end" data-bs-scroll="true" tabindex="-1" id="offcanvasWithBothOptions" aria-labelledby="offcanvasWithBothOptionsLabel">
            <div class="offcanvas-header justify-content-between">
                <h5 class="offcanvas-title text-center" id="offcanvasWithBothOptionsLabel">STORE LISTS</h5>
                <button type="button" class="btn-close" data-bs-dismiss="offcanvas" aria-label="Close"></button>
            </div>
            <div v-if="loadingStores" v-html="waitIndicator()"></div>
            <div v-else class="offcanvas-body">
                <div class="row">
                    <div class="col-12">

                         <!-- Search input for meetings -->
                        <div class="mb-3 d-flex gap-2 align-items-center">
                            <div class="flex-grow-1">
                                <global-search-field
                                    v-model:filterValue="filteredStores"
                                />
                            </div>
                        </div>
            
                        <div class="list-group text-start" id="list-tab" role="tablist">
                            <a 
                                v-for="store in searchedStores" 
                                :key="store.id" 
                                @click="selectedStore = store"
                                class="list-group-item list-group-item-action" 
                                :class="{ 'active': selectedStore?.id === store.id }"
                                data-bs-dismiss="offcanvas"
                                href="javascript:void(0);"
                            >
                                {{ store.name }}
                            </a>
                        </div>
                        
                    </div>
                </div>
            </div>
        </div>
        <!-- offcanvas ends -->

        <div class="my-4">
            <!-- item registration form starts -->
            <form v-if="conversion_factor" class="mt-3 p-3 border rounded bg-white shadow" @submit.prevent="registerBinCard">
                <h4 class="text-center">REGISTER BIN CARD </h4>

                <div class="row mb-2">

                    <div class="col-md-5" v-if="selectedStore.id === 'all'">
                        <label class="form-label small">Select Store</label>
                        <multiselect 
                            v-model="store"
                            :options="storeLists"
                            placeholder="Select Store"
                            label="name"
                            :searchable="true"        
                            :multiple="false"
                            :required="true"
                            :allow-empty="false"
                        ></multiselect>
                    </div>
                    
                    <div class="col-md-5">
                        <label class="form-label small">Select Item </label>
                        <div v-if="loadingStoreItems" v-html="waitIndicator()"></div>
                        <multiselect 
                            v-else
                            v-model="storeItem"
                            :options="storeItems"
                            placeholder="select item"
                            label="name"
                            :searchable="true"        
                            :multiple="false"
                            :required="true"
                            :allow-empty="false"
                        ></multiselect>
                    </div>
                </div>
                <div class="text-center gap-2 justify-content-end">
                    <button type="button" class="btn btn-danger me-3" @click="conversion_factor = false; resetForm();">Cancel</button>
                    <button type="submit" class="btn btn-primary">Register</button>
                </div>
            </form>
            <!-- item registration form ends-->
        </div>


        <!-- Bin Cards List -->
         <div v-if="!loading_spinner">
        <div class="accordion accordion-flush" id="accordionFlushExample">
            <div class="accordion-item" v-for="(binCard, index) in filteredBinCardsWithBalance" :key="binCard.id">
                <h2 class="accordion-header">
                    <button class="accordion-button collapsed" type="button" 
                        :data-bs-toggle="'collapse'" 
                        :data-bs-target="'#flush-collapse-' + binCard.id" 
                        aria-expanded="false" 
                        :aria-controls="'flush-collapse-' + binCard.id">
                        {{ index + 1 }} : &nbsp;&nbsp; {{ binCard.name ?? binCard.store_item?.item?.name }} &nbsp;&nbsp;   {{  binCard.store_item?.item?.description }} &nbsp;&nbsp; {{  binCard.store_item?.item_condition }}  &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; : &nbsp; {{ binCard.balance }}  &nbsp; {{ binCard.unit_name || binCard.store_item?.item?.unit }}  &nbsp; {{ binCard.description }} ID:{{ binCard.id }}
                    </button>
                </h2>
                <div :id="'flush-collapse-' + binCard.id" class="accordion-collapse collapse" :data-bs-parent="'#accordionFlushExample'">
                    <div class="accordion-body">
                        <div class="d-flex justify-content-end mb-3">  
                            <button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#add-item-modal" @click="openAddItemModal(binCard)" v-if="user_permissions.includes('can_add_store_items')"> 
                                <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" fill="currentColor" class="bi bi-plus-square" viewBox="0 0 16 16">
                                    <path d="M14 1a1 1 0 0 1 1 1v12a1 1 0 0 1-1 1H2a1 1 0 0 1-1-1V2a1 1 0 0 1 1-1zM2 0a2 2 0 0 0-2 2v12a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V2a2 2 0 0 0-2-2z"/>
                                    <path d="M8 4a.5.5 0 0 1 .5.5v3h3a.5.5 0 0 1 0 1h-3v3a.5.5 0 0 1-1 0v-3h-3a.5.5 0 0 1 0-1h3v-3A.5.5 0 0 1 8 4"/>
                                </svg>
                            </button>
                            <button class="btn btn-success ms-2" @click="printBinCard(binCard)">
                                <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" fill="currentColor" class="bi bi-printer" viewBox="0 0 16 16">
                                    <path d="M2.5 8a.5.5 0 1 0 0-1 .5.5 0 0 0 0 1"/>
                                    <path d="M5 1a2 2 0 0 0-2 2v2H2a2 2 0 0 0-2 2v3a2 2 0 0 0 2 2h1v1a2 2 0 0 0 2 2h6a2 2 0 0 0 2-2v-1h1a2 2 0 0 0 2-2V7a2 2 0 0 0-2-2h-1V3a2 2 0 0 0-2-2zM4 3a1 1 0 0 1 1-1h6a1 1 0 0 1 1 1v2H4zm1 5a2 2 0 0 0-2 2v1H2a1 1 0 0 1-1-1V7a1 1 0 0 1 1-1h12a1 1 0 0 1 1 1v3a1 1 0 0 1-1 1h-1v-1a2 2 0 0 0-2-2zm7 2v3a1 1 0 0 1-1 1H5a1 1 0 0 1-1-1v-3a1 1 0 0 1 1-1h6a1 1 0 0 1 1 1"/>
                                </svg>
                            </button>
                        </div> 

                        <div class="panel p-0 mt-3">                            
                            <div class="custom-table table3 mt-3">
                                <v-client-table 
                                    :data="getTableData(binCard.items)" 
                                    :columns="item_columns" 
                                    :options="table_option">
                                    <template #actions="props">
                              
                                <a href="javascript:;" class="edit me-3" @click="openEditItemModal(props.row)" data-bs-toggle="modal" :data-bs-target="'#edit-conversion-factor-modal'" v-if="user_permissions.includes('can_edit_bin_card_items')">
                                    <svg
        xmlns="http://www.w3.org/2000/svg"
        width="24"
        height="24"
        viewBox="0 0 24 24"
        fill="none"
        stroke="currentColor"
        stroke-width="1.5"
        stroke-linecap="round"
        stroke-linejoin="round"
        class="text-primary"
        style="cursor: pointer;"
        title="Edit Activity"
      >
        <path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"></path>
        <path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"></path>
      </svg>
                                </a>
                                <a href="javascript:;" class="cancel" @click="deleteBinCardItem(props.row)" v-if="user_permissions.includes('can_delete_bin_card_items')">
                                    <span 
                                        v-if="deletingItemId === props.row.id"
                                        class="spinner-border spinner-border-sm text-danger" 
                                        role="status" 
                                        aria-hidden="true"
                                        style="width: 24px; height: 24px;"
                                    ></span>
                                    <svg
                                        v-else
                                        xmlns="http://www.w3.org/2000/svg"
                                        width="24"
                                        height="24"
                                        viewBox="0 0 24 24"
                                        fill="none"
                                        stroke="currentColor"
                                        stroke-width="1.5"
                                        stroke-linecap="round"
                                        stroke-linejoin="round"
                                        class="text-danger"
                                    >
                                        <polyline points="3 6 5 6 21 6"></polyline>
                                        <path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"></path>
                                    </svg>
                                </a>
                            </template>
                                </v-client-table>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
            <!-- No bin cards found message -->
            <div v-if="filteredBinCardsWithBalance.length === 0 && selectedStore && !loading_spinner" class="alert alert-light text-center">
                No bin cards found for the selected store
            </div>
          
        </div>
        </div>
    </div>

    <!-- add binCard item starts -->
    <div class="modal fade mymodal" id="add-item-modal" data-bs-backdrop="false" data-bs-keyboard="false" tabindex="-1" aria-labelledby="itemModalLabel" aria-hidden="true">
        <div class="modal-dialog modal-xl">
            <div class="modal-content">
                <div class="modal-header">
                    <h1 class="modal-title fs-5" id="itemModalLabel">Add Bin Card Entry For {{ binCard.name ?? binCard.store_item?.item?.name }}</h1>
                    <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close" @click="closebinCardModal()" id="close_item"></button>
                </div>
                <form @submit.prevent="AddBinCardItem()">
                    <div class="modal-body">
                        <div class="row mb-3">
                            <div class="col-md-4">
                                <label for="quantity"> Ref No</label>
                                <input type="number" v-model="ref_no" class="form-control" placeholder="Enter Ref No" step="any" required >
                            </div>
                            <div class="col-md-4">
                                <label for="quantity"> Received Quantity</label>
                                <input type="number" v-model="received" class="form-control" placeholder="Enter Received Quantity" step="any" >
                            </div>
                            <div class="col-md-4">
                                <label for="quantity"> Isused Quantity</label>
                                <input type="number" v-model="issued" class="form-control" placeholder="Enter Issued Quantity" step="any" >
                            </div>
                            <div class="col-md-12">
                                <label for="remark"> Remark</label>
                                <input type="text" v-model="remark" class="form-control" placeholder="Enter Remark">
                            </div>
                        </div>
                    </div>
                    <div class="modal-footer">
                        <button type="button" class="btn btn-danger" data-bs-dismiss="modal" @click="closebinCardModal()" id="close_item">Close</button>
                        <button class="btn btn-primary me-2 mt-1" :disabled="isSending">
                            <span v-if="isSending" v-html="loadingSpinner()"></span>
                            <span>Save</span>
                        </button>
                    </div>
                </form>
            </div>
        </div>
    </div>
    <!-- add binCard item ends -->

             <!-- Edit bin card item  modal starts -->
<div class="modal fade mymodal" id="edit-conversion-factor-modal" data-bs-backdrop="false" data-bs-keyboard="false" tabindex="-1" aria-labelledby="editConversionFactorModalLabel" aria-hidden="true">
  <div class="modal-dialog modal-xl">
    <div class="modal-content">
      <div class="modal-header">
        <h1 class="modal-title fs-5" id="editConversionFactorModalLabel">Edit Conversion Factor</h1>
        <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close" @click="closeEditModal()"></button>
      </div>
      <form @submit.prevent="updateBinCardItem(bin_card_item_id)">
        <div class="modal-body">
            <div class="row mb-3">
                <div class="col-md-4">
                                <label for="quantity"> Ref No</label>
                                <input type="number" v-model="ref_no" class="form-control" placeholder="Enter Ref No" step="any">
                 </div>
                <div class="col-md-4">
                <label for="quantity"> Received Quantity</label>
              <input type="number" v-model="received" class="form-control" placeholder="Enter Quantity" step="any">
            </div>
            <div class="col-md-4">
                <label for="quantity"> Issued Quantity</label>
              <input type="number" v-model="issued" class="form-control" placeholder="Enter Quantity" step="any">
            </div>
            <div class="col-md-12">
                                <label for="remark"> Remark</label>
                                <input type="text" v-model="remark" class="form-control" placeholder="Enter Remark">
                            </div>
          </div>
        </div>
        <div class="modal-footer">
          <button type="button" class="btn btn-secondary" data-bs-dismiss="modal" @click="closeEditModal()" id="close_editing">Close</button>
          <button type="submit" class="btn btn-primary">
            <span v-if="loading_spinner" class="spinner-border spinner-border-sm text-white me-2" role="status"></span>
            Edit
          </button>
        </div>
      </form>
    </div>
  </div>
</div>
<!-- Edit bin card item modal ends -->
</template>

<script setup>
    import { onMounted, ref, inject, watch, computed } from 'vue';
    import axios from 'axios';
    import { useMeta } from '@/composables/use-meta';
    import Multiselect from '@suadelabs/vue3-multiselect';
    import '@suadelabs/vue3-multiselect/dist/vue3-multiselect.css';
    import globalSearchField from '@/components/reusables/globalSearchField.vue';
    import { globalSearch } from '@/components/reusables/globalSearch';
    
    useMeta({ title: 'Bin Cards' });  
    const loadingIndicator = inject('loadingIndicator');
    const waitIndicator = inject('waitIndicator');
    const showMessage = inject('showMessage');
    const conversion_factor = ref(false);
    const showError = inject('showError');
    const user_permissions = JSON.parse(localStorage.getItem("user")).permissions;
    const formatDate = inject('formatDate');
    const tableShimmer = inject('tableShimmer');
    const loadingSpinner = inject('loadingSpinner'); 
    const filter = ref('')
    
    const loading_spinner = ref(false);
    const item_columns = ref(['SNo','date','ref_no','received_Qty','issued_Qty','balance_Qty','remark','authorized_by','actions']);    
    const name = ref('');
    const remark = ref('');
    const description = ref('');
    const units = ref('');
    const source = ref('')
    const stores = ref([])
    const selectedStore = ref(null) // Changed from store to selectedStore for clarity
    const selectAllStores = () => {
  selectedStore.value = { id: 'all', name: 'All bin cards' }
}

const filteredStores = ref('')
const searchedStores = computed(() => {
  return globalSearch(stores.value, filteredStores.value)
})
    
    const table_option = ref({
        perPage: 20,
        perPageValues: [20, 50 ,100],
        skin: 'table table-hover table-striped',
        columnsClasses: { actions: 'actions text-center' },
        sortable: ['SNo', 'ref_no','received_Qty','issued_Qty','balance_Qty'],
        sortIcon: {
            base: 'sort-icon-none',
            up: 'sort-icon-asc',
            down: 'sort-icon-desc',
        },
        pagination: { nav: 'scroll', chunk: 5 },
        texts: {
            count: 'Showing {from} to {to} of {count}',
            filter: '',
            filterPlaceholder: 'Search...',
            limit: 'Results:',
        },
        resizableColumns: false,
    });

    const axiosInstance = axios.create({
        baseURL: process.env.VUE_APP_API_BASE_URL
    });

    const unitList = ref([]);
    const getUnits = async () => {
        try {
            const response = await axiosInstance.get('/units');
            unitList.value = response.data;
        } catch (error) {
            showError(error.message);
        }
    };

    const binCards = ref([]);
    
    // Function to calculate balance for table data
    const getTableData = (items) => {
        if (!items) return [];
        
        let runningBalance = 0;
        return items.map((item, index) => {
            const received = parseFloat(item.received) || 0;
            const issued = parseFloat(item.issued) || 0;
            runningBalance += received - issued;
            
            return {
                ...item,
                SNo: index + 1,
                received_Qty: Number(item.received) > 0 ? Number(item.received).toLocaleString() : '---',
                issued_Qty: Number(item.issued) > 0 ? Number(item.issued).toLocaleString() : '---',
                balance_Qty: Number(runningBalance).toLocaleString(),
                date: formatDate(item.created_at),
                authorized_by: item.issuer?.name || 'N/A',
            };
        });
    };


  const filteredBinCards = computed(() => {
    return globalSearch(binCards.value, filter.value)
})


    const filteredBinCardsWithBalance = computed(() => {
        return filteredBinCards.value.map(binCard => {
            if (!binCard.items || binCard.items.length === 0) {
                return {
                    ...binCard,
                    balance: 0
                };
            }

            const totalBalance = binCard.items.reduce((balance, item) => {
                const received = parseFloat(item.received) || 0;
                const issued = parseFloat(item.issued) || 0;
                return balance + (received - issued);
            }, 0);

            return {
                ...binCard,
                balance: totalBalance.toFixed(2)
            };
        });
    });

   const getBinCards = async (showLoading = true) => {
  if (showLoading) loading_spinner.value = true;

  try {
    let url = 'bin-cards';

    if (selectedStore.value && selectedStore.value.id !== 'all') {
      url += `?store_id=${selectedStore.value.id}`;
    }

    const response = await axiosInstance.get(url);

    binCards.value = response.data.map((item, index) => ({
      ...item,
      SNo: index + 1,
      id: item.id,
      name: item.name,
      unit: item.unit,
      unit_name: item.unit,
      description: item.description,
      remark: item.remark,
      items: item.items,
    }));
  } catch (error) {
    showError(error.message);
  } finally {
    if (showLoading) loading_spinner.value = false;
  }
};

    
    const registerBinCard = async () => {
        const existingBinCard = binCards.value.find(card => {
            
            if (source.value === 'general' && card.name === name.value) {
                return true;
            }
            // Check by store_item_id if source is store
            if (source.value === 'store' && storeItem.value && card.store_item_id === storeItem.value.id) {
                return true;
            }
            return false;
        });

        if (existingBinCard) {
            showError('A bin card already exists!');
            return;
        }
        conversion_factor.value = false;
        const itemData = {
            name: name.value ??  storeItem.value.name ,
            unit: units.value.short_name,
            description: description.value,
            remark: remark.value,
            store_item_id : storeItem.value.id ?? '' ,
            issuer_id : JSON.parse(localStorage.getItem('user')).id
        };
    
        try {
            const response = await axiosInstance.post('/bin-cards', itemData);
            getBinCards(false);
            showMessage('Bin Card registered!');
            resetForm();
        } catch (error) {
            showError(error.message);
            console.log(error)
        }
    };    

    const resetForm = () => {
        name.value = '';
        units.value = '';
        description.value = '';
        storeItem.value = ''
        storeItems.value = []
        store.value = ''
        source.value = ''
    };

    const openAddItemModal = (row) => {
        bin_card_id.value = row.id; 
        binCard.value = row;
    };

    const isSending = ref(false);
    const received = ref('');
    const issued = ref('');
    const bin_card_id = ref('');
    const ref_no = ref('');
    const item = ref('');
    const binCard = ref('');
    const store = ref(''); // This is for the form, keep as is

    const AddBinCardItem = async () => {
        isSending.value = true;
        const itemData = {
            bin_card_id: bin_card_id.value, 
            ref_no: ref_no.value,    
            received: received.value,
            issued: issued.value,
            issuer_id: JSON.parse(localStorage.getItem("user")).id,
            remark: remark.value,
        };
        try {  
            const response = await axiosInstance.post(`bin-card-items`, itemData)
            await getBinCards(false) 
            document.getElementById('close_item').click();
            showMessage('Bin Card Item added')
        } catch(error) {
            console.log(error)
            showError(error.message)
        } finally {
            isSending.value = false;    
        }
    };

    const closebinCardModal = () => {
        ref_no.value = '';
        received.value = '';
        issued.value = '';
        remark.value = '';
    };

    const printBinCard = (binCard) => {
        const iframe = document.createElement('iframe');
        iframe.style.position = 'absolute';
        iframe.style.width = '0';
        iframe.style.height = '0';
        iframe.style.border = 'none';
        document.body.appendChild(iframe);

        const tableData = getTableData(binCard.items);
        const tableRows = tableData.map(row => `
            <tr>
                <td>${row.SNo}</td>
                <td>${row.ref_no}</td>
                <td>${row.received_Qty}</td>
                <td>${row.issued_Qty}</td>
                <td>${row.balance_Qty}</td>
                <td>${row.remark}</td>
                <td>${row.authorized_by}</td>
                <td>${row.date}</td>      
            </tr>
        `).join('');

        const currentDate = new Date().toLocaleDateString('en-GB', {
            day: '2-digit',
            month: '2-digit',
            year: 'numeric'
        });

        const printContent = `
            <!DOCTYPE html>
            <html>
            <head>
            <title>Bin Card - ${binCard.name ?? binCard.store_item?.item?.name}</title>
           <style>
  body { font-family: 'Courier New', monospace; margin: 20px; font-size: 11px; }
  .text-style { font-family: 'Courier New', monospace; }
